use crate::{mscq02 as m,model::*,unit_support::*};
#[test]
fn mscq02_red_original_closed_construction(){let s=crate::society::definition(m::ID).unwrap();assert_eq!(s.starting_hand,5);assert_eq!(s.card.color,"红");assert!(!s.card.supported);for c in &crate::catalog::catalog().cards{let expected=matches!(c.color.as_str(),"红"|"中立")||c.subtypes.iter().any(|s|matches!(s.as_str(),"灾难"|"时间"|"命运"));assert_eq!(crate::society::validate_construction(s,&[crate::catalog::DeckEntry{card_id:c.id.clone(),count:1}],&crate::catalog::catalog().cards).is_ok(),expected,"{}",c.id);}}
fn own(g:&mut Game,seat:usize){g.players[seat].society_zone.card=Some(g.make_card(m::ID,seat));}
fn natural(seed:u64)->(Game,crate::deck::DeckDraft){let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-norvi".into();d.name="诺尔维封闭自然测试".into();d.description="50张既有无知路人；非官方预组".into();d.society_id=Some(m::ID.into());d.cards=vec![crate::catalog::DeckEntry{card_id:"JC125".into(),count:50}];assert!(crate::deck::validate(d.clone()).is_err());let mut societies=crate::catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let d=crate::deck::validate_with_registry(d,&crate::catalog::catalog().cards,&societies).unwrap();let mut other=d.clone();other.society_id=None;let other=crate::deck::validate(other).unwrap();let mut g=Game::new("norvi".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
#[test]
fn mscq02_start_optional_original_third_region_and_decline(){for accept in [false,true]{let(mut g,_)=natural(4);assert_eq!(g.players[0].hand.len(),5);assert!(!g.regions[2].destroyed);let id=g.regions[2].card.id.clone();assert_eq!(g.pending.as_ref().unwrap().choice.min,Some(0));choose(&mut g,if accept{vec!["accept".into()]}else{vec![]});for _ in 0..32{if let Some(p)=&g.pending{if matches!(p.resolution,ChoiceResolution::Declare{..}){panic!("unexpected second start");}resolve_choice(&mut g);}else if !g.stack.is_empty(){pass(&mut g);}else{break;}}assert_eq!(g.regions[2].destroyed,accept);assert_eq!(g.regions[2].card.id,id);assert!(g.regions.iter().enumerate().all(|(r,x)|r==2||!x.destroyed));g.mscq02_observe_start();assert!(!g.effects.iter().any(|e|matches!(e,Effect::Declare{declaration:d}if d.source.card.definition==m::ID)));restore(&mut g);}}
#[test]
fn mscq02_start_replaced_slot_does_not_destroy_new_region(){let(mut g,_)=natural(4);choose(&mut g,vec!["accept".into()]);while g.pending.is_some(){resolve_choice(&mut g);}let original=g.regions[2].card.id.clone();g.regions[2].card=g.make_card("DQJC115",0);crate::jc029_tests::pass_top(&mut g);assert_ne!(g.regions[2].card.id,original);assert!(!g.regions[2].destroyed);restore(&mut g);}
#[test]
fn mscq02_continuous_global_physical_four_idempotent_and_departure(){let mut g=game();own(&mut g,0);let a=field(&mut g,"JC125",2);g.board_mut(&a).unwrap().time_markers=2;g.regions[0].card.time_markers=1;g.mscq02_continuous();assert!(!g.regions[0].destroyed);g.board_mut(&a).unwrap().time_markers=3;assert!(Game::from_persisted(&serde_json::to_string(&g).unwrap()).is_err());g.drive().unwrap();assert!(g.regions[0].destroyed);g.board_mut(&a).unwrap().time_markers=0;g.mscq02_continuous();assert!(g.regions[0].destroyed);assert!(g.board(&a).is_some());restore(&mut g);
 let mut g=game();own(&mut g,0);g.players[0].society_zone.card.as_mut().unwrap().face_down=true;g.regions[1].card.time_markers=4;g.mscq02_continuous();assert!(!g.regions[1].destroyed);g.players[0].society_zone.card.as_mut().unwrap().face_down=false;g.drive().unwrap();assert!(g.regions[1].destroyed);restore(&mut g);}
#[test]
fn mscq02_win_exact_owner_destroyed_gate_optional_draw_and_replacement(){for (seat,destroyed,accept) in [(0,true,true),(0,true,false),(0,false,true),(1,true,true),(2,true,true)]{let mut g=game();own(&mut g,0);g.regions[0].destroyed=destroyed;let before=g.players[0].hand.len();let old=g.regions[0].card.id.clone();g.effect(Effect::Score{seat,region:0}).unwrap();g.drive().unwrap();let observed=seat==0&&destroyed;let mut saw=false;for _ in 0..64{if let Some(p)=g.pending.clone(){let ours=matches!(&p.resolution,ChoiceResolution::Declare{declaration,..}if declaration.source.card.definition==m::ID);if ours{saw=true;}choose(&mut g,if ours&&accept{vec!["accept".into()]}else{vec![]});}else if !g.stack.is_empty(){pass(&mut g);}else{break;}}assert_eq!(saw,observed);assert_eq!(g.players[0].hand.len(),before+usize::from(observed&&accept));assert_ne!(g.regions[0].card.id,old);assert!(!g.regions[0].destroyed);restore(&mut g);}}
#[test]
fn mscq02_corrupt_observation_duplicate_queue_and_program_rejected(){let(g,_)=natural(4);for case in 0..4{let mut bad=g.clone();let d=match &mut bad.pending.as_mut().unwrap().resolution{ChoiceResolution::Declare{declaration,..}=>declaration,_=>panic!()};match case{0=>d.source.card.definition="MSJC09".into(),1=>d.ability.ops.clear(),2=>{if let crate::rules::Op::MSCQ02{observation:Some(o)}=&mut d.ability.ops[0]{o.instance="i999999999".into();}},_=>bad.effects.push_back(Effect::Declare{declaration:d.clone()})}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}let mut bad=m::definition();bad.abilities[0].costs.push(crate::rules::Cost::Assets(1));assert!(m::validate_definition(m::ID,&bad).is_err());}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(s["command"].clone()).unwrap();let d=room.transition(s["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]
fn mscq02_natural_start_conceal_win_draw_and_actual_clock_response_room_chain(){use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..129).find_map(|seed|{let(g,d)=natural(seed);(g.regions[2].card.definition=="DQJC115").then_some((seed,g,d))}).expect("bounded seed finds original generic third region");let mut t=Trace::new_preserving_rng(g,"mscq02-natural-third-region-win".into(),650);let mut won=false;let mut draw_accepted=false;let mut before_draw=0;let mut done=false;
 for _ in 0..1400{if let Some(p)=t.room.game.pending.clone(){if matches!(p.resolution,ChoiceResolution::Bottom{..}){let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),bottom:Some(ids),..Action::new("choose")});continue;}let ids=if matches!(&p.resolution,ChoiceResolution::Declare{declaration,..}if declaration.source.card.definition==m::ID){if matches!(&p.resolution,ChoiceResolution::Declare{declaration,..}if declaration.ability.key==m::WIN){won=true;before_draw=t.room.game.players[0].hand.len();draw_accepted=true;}vec!["accept".into()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);continue;}
 if draw_accepted&&t.room.game.stack.is_empty(){assert_eq!(t.room.game.players[0].hand.len(),before_draw+1);done=true;break;}
 let legal=t.room.game.legal_actions(0);let a=if t.room.game.players[0].assets.is_empty(){legal.iter().find(|a|a.action.kind=="asset")}else{legal.iter().find(|a|a.action.kind=="conceal"&&a.action.region==Some(2))};if let Some(a)=a{t.action(0,a.action.clone());}else{t.pass();}}
 assert!(won&&done,"natural loop at turn {}",t.room.game.turn);let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"admission":"private candidate registry only","noLayoutOrResourceMutation":true});let natural=duplicate(v);
 let mut g=game();own(&mut g,0);g.players[1].society_zone.card=Some(g.make_card("MSJC13",1));fund(&mut g,1,"JC125",2);let target=field(&mut g,"JC125",2);g.board_mut(&target).unwrap().time_markers=3;let source=g.players[1].society_zone.card.as_ref().unwrap().id.clone();let mut t=Trace::new(g,"mscq02-prepared-four-time-actual-clock-action".into(),651);t.action(1,Action{card_id:Some(source),ability_id:Some(crate::batch4_clock::ADD.into()),target_id:Some(target),..Action::new("activate")});for _ in 0..32{if t.room.game.stack.is_empty(){break;}t.pass();}assert!(t.room.game.regions[0].destroyed);let prepared=duplicate(t.value());
 if let Ok(path)=std::env::var("MSCQ02_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":source_bindings(),"cases":[natural,prepared]})).unwrap()).unwrap();}}
fn source_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut b=crate::jc066_tests::source_bindings();for(n,bytes)in[("rust-game/src/mscq02.rs",include_bytes!("mscq02.rs").as_slice()),("rust-game/src/mscq02_tests.rs",include_bytes!("mscq02_tests.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(n.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}b}

#[test]
fn mscq02_multiple_opening_triggers_first_team_order_and_idempotent_destruction(){let mut g=game();own(&mut g,0);own(&mut g,2);g.first_team=1;g.mscq02_observe_start();let actors=g.effects.iter().filter_map(|e|if let Effect::Declare{declaration:d}=e{(d.source.card.definition==m::ID).then_some(d.actor)}else{None}).collect::<Vec<_>>();assert_eq!(actors,[2,0]);g.drive().unwrap();for _ in 0..64{if g.pending.is_some(){choose(&mut g,vec!["accept".into()]);}else if !g.stack.is_empty(){pass(&mut g);}else{break;}}assert!(g.regions[2].destroyed);assert_eq!(g.destroyed_region_count(),1);restore(&mut g);}

#[test]
fn mscq02_internal_receipts_are_not_once_per_game_public_abilities(){let(mut g,_)=natural(4);assert!(!g.players[0].society_zone.mscq02_observed.is_empty());assert!(g.players[0].society_zone.used_once_per_game.is_empty());for seat in 0..4{let v=serde_json::to_value(g.view(seat)).unwrap();assert!(v["societyZones"][0]["card"].get("usedOncePerGame").is_none());}restore(&mut g);}
